import MarkdownPage from './MarkdownPage.js';

export function renderHTMLDocument({ title = '', description = '', content = '', components = {} } = {}) {
    return `<!DOCTYPE html>
<!-- Generated by scripts/render-pages.mjs. Run npm run render after editing the sources. -->
<html lang="en">

<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>${escapeHTML(title ? `${title} | Erich Zimmer` : 'Erich Zimmer')}</title>
    <meta name="description" content="${escapeAttr(description)}">
    <link rel="stylesheet" href="/styles.css">
</head>

<body>
    <div class="app-shell">
        <aside class="sidebar" aria-label="Site sidebar">
            <div data-component="header">${components.header || ''}</div>
            <div data-component="nav">${components.nav || ''}</div>
            <div class="sidebar-spacer" aria-hidden="true"></div>
            <div data-component="footer">${components.footer || ''}</div>
        </aside>

        <main id="app" class="content" tabindex="-1" aria-live="polite" data-rendered="${Boolean(content)}">
${content}
        </main>
    </div>

    <script type="module" src="/modules/app.js"></script>
</body>

</html>
`;
}

export function renderHomeMarkup() {
    return `
        <section class="center-zone">
            <article class="panel hero">
                <p class="eyebrow">Home</p>
                <h1>Research, blogs, projects, and PIV utilities.</h1>
            </article>

            <section class="home-grid" aria-label="Site sections">
                ${homeCard('/research.html', 'Research', 'Project summaries and technical research.')}
                ${homeCard('/blogs.html', 'Blogs', 'General posts, updates, and notes.')}
                ${homeCard('/projects.html', 'Projects', 'Open source hardware and software projects.')}
                ${homeCard('/piv-utilities.html', 'PIV Utilities', 'Calculator for maximum allowable velocity from FOV, resolution, blur, and pulse length.')}
            </section>

            <article class="panel">
                <div class="panel-body">
                    <h2>About</h2>
                    <p>
                        I am a graduate in computer science with a focus on
                        machine learning and ethics. I am also a research
                        enthusiast and love electrical engineering and fluid
                        dynamics. This has led to efforts on my behalf to design
                        and construct open source and low-cost hardware and
                        software to further my self-studies along with those
                        who suffer from stingent funding allocations. More
                        information on these projects can be seen in the research
                        page along with some miscellaneous information in the
                        blog page.
                    </p>
                </div>
            </article>
        </section>`;
}

function homeCard(href, title, description) {
    return `
        <a class="card" href="${href}">
            <p class="eyebrow">Open</p>
            <h2>${escapeHTML(title)}</h2>
            <p>${escapeHTML(description)}</p>
        </a>`.trim();
}

export function renderCollectionMarkup(collection) {
    const listHTML = collection.items.map((item) => contentCard(item)).join('');
    return `
        <section class="center-zone">
            <article class="panel page-title">
                <p class="eyebrow">${escapeHTML(collection.title)}</p>
                <h1>${escapeHTML(collection.title)}</h1>
                <p>${escapeHTML(collection.description)}</p>
            </article>

            <article class="panel">
                <div class="toolbar">
                    <strong>${collection.items.length} ${collection.items.length === 1 ? 'page' : 'pages'}</strong>
                    <input id="content-search" class="search-input" type="search" placeholder="Search title, date, or tags" aria-label="Search ${escapeHTML(collection.title)}">
                </div>
                <div class="panel-body">
                    <section id="content-list" class="card-grid" aria-label="${escapeHTML(collection.title)} list">
                        ${listHTML || '<p class="empty-state">No pages were found.</p>'}
                    </section>
                </div>
            </article>
        </section>`;
}

export function contentCard(item) {
    const tags = item.tags.map((tag) => `<li class="tag">${escapeHTML(tag)}</li>`).join('');
    return `
        <a class="content-card" href="${escapeAttr(item.externalUrl || item.url)}" data-title="${escapeAttr(item.title)}">
            <div class="meta-row">
                ${renderMetaParts(item)}
            </div>
            <h2>${escapeHTML(item.title)}</h2>
            ${item.summary ? `<p>${escapeHTML(item.summary)}</p>` : ''}
            ${tags ? `<ul class="tag-list">${tags}</ul>` : ''}
        </a>`.trim();
}

function renderMetaParts(item, { includeWordCount = false } = {}) {
    const parts = [formatDate(item.date) || 'Undated'];

    if (item.readingTimeText) {
        parts.push(item.readingTimeText);
    }

    if (includeWordCount && item.wordCount) {
        parts.push(`${formatNumber(item.wordCount)} words`);
    }

    return parts
        .map((part) => `<span>${escapeHTML(part)}</span>`)
        .join('<span aria-hidden="true">·</span>');
}

export function renderArticleMarkup(collection, item, bodyHTML) {
    const tags = item.tags.map((tag) => `<li class="tag">${escapeHTML(tag)}</li>`).join('');
    return `
        <section class="center-zone">
            <article class="panel article">
                <header class="article-header">
                    <a class="back-link" href="/${collection.type}.html">← Back to ${escapeHTML(collection.title)}</a>
                    <p class="eyebrow">${escapeHTML(collection.title)}</p>
                    <h1>${escapeHTML(item.title)}</h1>
                    <div class="meta-row">
                        ${renderMetaParts(item, { includeWordCount: true })}
                    </div>
                    ${tags ? `<ul class="tag-list">${tags}</ul>` : ''}
                </header>
                <section class="markdown-body">
                    ${bodyHTML}
                </section>
            </article>
        </section>`;
}

function formatDate(value = '') {
    if (!value) {
        return '';
    }

    const date = new Date(`${value}T00:00:00`);
    if (Number.isNaN(date.getTime())) {
        return value;
    }

    return new Intl.DateTimeFormat(undefined, { year: 'numeric', month: 'short', day: 'numeric' }).format(date);
}

function formatNumber(value = 0) {
    return new Intl.NumberFormat(undefined).format(value);
}

function escapeHTML(value = '') {
    return MarkdownPage.escapeHTML(value);
}

function escapeAttr(value = '') {
    return MarkdownPage.escapeAttr(value);
}
